  const instruction=entry.kind==='fixed'?entry.steps.join(' '):'Check your known crafting diagrams first. Visit the listed seller and look for the diagram, not the finished item. Buy only if it is offered and you need it. Source-listed stock is provisional; actual availability can differ. There is no guaranteed chest for this merchant entry.';
  tasks[entry.id]={name:entry.name,home:entry.home,view:entry.view,type:'diagram',diagram:true,map:true,category:'gear',intro:entry.kind==='fixed'?entry.alias+' · '+entry.location:'Merchant acquisition lead · check current stock',why:'A shared diagram entry referenced by nearby quest clusters and the regional diagram deck.',requirements:entry.kind==='fixed'?'Suggested hunt level 6. Clear the guarded approach before looting.':'Stock lead, not guaranteed inventory. Check what is offered in your playthrough.',reward:'Acquire the diagram only. Crafting requirements and equipment statistics are outside this slice.',completionDefinition:'Diagram acquired in game; viewing this entry does not acquire it.',sections:[['Acquisition',instruction]],sources:entry.kind==='fixed'?[entry.source]:entry.vendors.map(v=>vendors[v].source),diagramPoint:entry.point};
  for(const hid of entry.clusters){const h=hubs.find(h=>h.id===hid);if(!h)throw Error('Diagram cluster missing: '+hid);if(!h.items.includes(entry.id))h.items.push(entry.id);}
